#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 10
static long heap[CAPACITY];
static int size = 0;

static void swap(int i, int j) {
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

static int heap_insert(long v) {
    if (size == CAPACITY) {
        puts("FULL");
        return 1;
    }
    int i = size;
    heap[i] = v;
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] <= heap[i]) break;
        swap(parent, i);
        i = parent;
    }
    ++size;
    printf("INS %ld\n", v);
    return 0;
}

static void heap_min(void) {
    if (size == 0) {
        puts("EMPTY");
    } else {
        printf("MIN %ld\n", heap[0]);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    for (int idx = 1; idx < argc; ++idx) {
        char *arg = argv[idx];
        if (arg[0] == 'I') {
            if (arg[1] == '\0') {
                puts("ERR");
                continue;
            }
            char *endptr;
            long val = strtol(arg + 1, &endptr, 10);
            if (endptr == arg + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }
            heap_insert(val);
        } else if (strcmp(arg, "M") == 0) {
            heap_min();
        } else {
            puts("ERR");
        }
    }
    return 0;
}
